7|Matrix::Matrix(std::size_t rows, std::size_t cols)
8|    : rows_(rows), cols_(cols), data_(rows * cols, 0.0) {
9|    if (rows == 0 || cols == 0) {
10|        throw std::invalid_argument("Matrix dimensions must be non-zero");
11|    }
12|}
